//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between attempts, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay before the retry numbered `retry_number` (starting at 1).
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let exponent = retry_number.saturating_sub(1);
        let multiplier = 1u64.checked_shl(exponent).unwrap_or(u64::MAX);
        self.base_delay_ms
            .saturating_mul(multiplier)
            .min(self.max_delay_ms)
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 0;

    loop {
        attempt += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(4, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&config(3, 7, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![7, 14]);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

# jobrunner

Small job runner with a pluggable retry policy.

## Retry policy

`run_job` retries only `RetryError::Transient` failures. Permanent errors are
returned immediately. `RetryConfig::max_attempts` is the total number of job
calls, including the first call; a value of zero is treated as one attempt.

Retries wait using bounded exponential backoff: the first delay is
`base_delay_ms`, each subsequent delay doubles, and delays are capped at
`max_delay_ms`. The injected `Sleeper` makes the policy straightforward to
test without real waiting. `FakeSleeper` records requested delays.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 100,
    max_delay_ms: 1_000,
};
let mut sleeper = FakeSleeper::default();
let result = run_job(&config, &mut sleeper, || Ok::<_, RetryError>(()));
assert!(result.is_ok());
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn transient_failure_then_success_retries_and_succeeds() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("temporary outage".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![5, 8]);
}

#[test]
fn permanent_failure_is_not_retried() {
    let config = RetryConfig {
        max_attempts: 10,
        base_delay_ms: 5,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("bad request".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("bad request".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}
